\title{\flushleft Microscale modeling of high-temperature heat transfer in anisotropic porous materials}

\author[first]{Federico Semeraro\corref{cor1}} \ead{federico.semeraro@nasa.gov} \author[second]{Joseph C. Ferguson} \author[third]{Sadaf Sobhani} \author[second]{Arnaud Borner} \author[fourth]{Francesco Panerai} \author[fifth]{Nagi N. Mansour}

